#!/usr/bin/env python3
"""Bounded local verification of the method-learning artifacts.

Checks, over the local frozen inputs and the four artifacts written beside them:

  1  exactly one decision, drawn from create / amend / merge / no_change
  2  the missing outcome is never reported as zero
  3  no claim that external replication was performed
  4  the episode budget is one step

plus the bonds the local contract needs: every quoted passage in an artifact
resolves verbatim to a line of inputs.txt, the pinned base digest matches M1's
text, the relation vocabulary is respected, and the two artifacts that carry an
agenda delta agree with episode.json about budget and stopping reason.

Each numbered check is self-tested against a deliberately broken copy of the
data; a check that cannot fail is reported as such rather than counted.

Run:  python3 verify.py [--report verification-report.txt]
"""

from __future__ import annotations

import argparse
import copy
import hashlib
import json
import re
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
DECISIONS = ("create", "amend", "merge", "no_change")
RELATION_VOCABULARY = (
    "shared_part",
    "subset",
    "merge",
    "abstract_pattern",
    "conflicts_with",
    "supersedes",
)
LINE_RE = re.compile(r"^\[(E\d)\] digest: (sha256:[0-9a-f]{64})$")

# Prose that would assert a completed reproduction outside the teaching case,
# and the polarity guard that keeps an honest denial from matching.
REPLICATION_CLAIM = re.compile(
    r"(replicat\w*|reproduc\w*|independent(?:ly)?\s+(?:confirm\w*|verif\w*)|复现|重现|再现)"
    r"[^.;\n]{0,60}?(success\w*|confirm\w*|verif\w*|demonstrat\w*|achiev\w*|complet\w*|"
    r"done|reported|成功|完成|已确认|已验证|已复现)",
    re.I,
)
POLARITY_GUARD = re.compile(
    r"\b(not|never|no|none|without|unresolved|unperformed|absent|failed)\b|未|没有|不|尚",
    re.I,
)


def read(path: Path) -> str:
    return path.read_text(encoding="utf-8", errors="replace")


def load(path: Path):
    return json.loads(read(path))


def load_inputs() -> tuple[dict[str, str], dict[str, str]]:
    """Frozen teaching lines by evidence id, and the digest each line declares."""
    text: dict[str, str] = {}
    digest: dict[str, str] = {}
    for line in read(HERE / "inputs.txt").splitlines():
        match = LINE_RE.match(line.strip())
        if match:
            current = match.group(1)
            digest[current] = match.group(2)
            continue
        if line.strip():
            key = line.strip().split(" ", 1)[0]
            if key in digest and "digest" not in line:
                pass
    # second pass: the teaching line is the line following its digest line
    lines = read(HERE / "inputs.txt").splitlines()
    for index, line in enumerate(lines):
        match = LINE_RE.match(line.strip())
        if match and index + 1 < len(lines):
            text[match.group(1)] = lines[index + 1]
    return text, digest


def sha256_line(value: str) -> str:
    return "sha256:" + hashlib.sha256((value + "\n").encode("utf-8")).hexdigest()


def unresolved_quotes(quote_source_pairs, text) -> list[str]:
    """Quotes that do not appear verbatim in the frozen teaching text."""
    failures = []
    for source, quote in quote_source_pairs:
        haystack = text.get(source)
        if haystack is None:
            failures.append(f"{source}: no such frozen line")
        elif quote not in haystack:
            failures.append(f"{source}: quote not verbatim -> {quote[:70]!r}")
    return failures


def replication_claims(blobs: dict[str, str]) -> list[str]:
    hits = []
    for name, blob in blobs.items():
        for match in REPLICATION_CLAIM.finditer(blob):
            window = blob[max(0, match.start() - 90): match.end() + 40]
            if not POLARITY_GUARD.search(window):
                hits.append(f"{name}: {match.group(0)!r} in {window.strip()[:120]!r}")
    return hits


# --------------------------------------------------------------------------
# the checks: each takes a data bundle and returns a list of failures
# --------------------------------------------------------------------------


def check_decision(bundle) -> list[str]:
    distillation = bundle["distillation"]
    values = {key: distillation.get(key) for key in ("decision", "operation")}
    problems = []
    present = [v for v in values.values() if v is not None]
    if len(present) != 2:
        problems.append(f"decision fields missing: {values}")
    if len(set(present)) != 1:
        problems.append(f"more than one decision value: {values}")
    for key, value in values.items():
        if value not in DECISIONS:
            problems.append(f"{key}={value!r} is outside {DECISIONS}")
    if distillation.get("mergedMethodIds"):
        problems.append("a single decision cannot also fold methods together")
    if distillation.get("operation") == "no_change" and not distillation.get("reason"):
        problems.append("no_change without a reason")
    return problems


def check_missing_not_zero(bundle) -> list[str]:
    """The unrecorded observations are never reported as a zero count."""
    problems = []
    distillation = bundle["distillation"]
    if distillation.get("operation") != "no_change":
        return ["this artifact set is not the no-change case; the check is skipped"]
    confirmed = next(
        (e for e in distillation.get("evidence", []) if e.get("id") == "EV4"), None
    )
    if confirmed is None:
        return ["the confirmed output is not recorded among the evidence entries"]
    counts = dict(re.findall(r"([a-z]+)\s*(\d+)", confirmed.get("quote", ""), re.I))
    unknown = None
    for key, value in counts.items():
        if key.startswith("missing") or key.startswith("unknown"):
            unknown = int(value)
    if unknown is None:
        problems.append("the confirmed output does not state the unrecorded count")
    elif unknown == 0:
        problems.append("the unrecorded count was reported as 0")
    elif unknown < 0:
        problems.append("the unrecorded count cannot be negative")
    known = next((int(v) for k, v in counts.items() if k.startswith("known")), None)
    denominator = next((int(v) for k, v in counts.items() if k.startswith("denominator")), None)
    if known is not None and denominator is not None and unknown is not None:
        if known + unknown != denominator:
            problems.append(
                f"counts do not reconcile: known {known} + unrecorded {unknown} != denominator {denominator}"
            )
        if known == denominator:
            problems.append("the known count equals the denominator, which leaves no room for the unrecorded one")
    episode = bundle["episode"]
    failures = episode.get("boundedNextAction", {}).get("failureTest", "")
    if "0" not in failures and "zero" not in failures.lower():
        problems.append("the episode's failure test does not treat a zero unknown count as a failure")
    return problems


def check_no_replication_claim(bundle) -> list[str]:
    hits = replication_claims(bundle["blobs"])
    return [f"replication asserted as done: {hit}" for hit in hits]


def check_budget_one(bundle) -> list[str]:
    problems = []
    episode = bundle["episode"]
    plan = episode.get("plan", {})
    steps = plan.get("steps", [])
    if plan.get("stepCount") != 1:
        problems.append(f"plan.stepCount is {plan.get('stepCount')!r}, not 1")
    if len(steps) != 1:
        problems.append(f"the plan carries {len(steps)} steps, not 1")
    if episode.get("agenda", {}).get("budgetSteps") != 1:
        problems.append("the agenda budget is not 1 step")
    if plan.get("withinBudget") is not True:
        problems.append("the plan does not declare itself within budget")
    stopping = " ".join(episode.get("stoppingReason", []))
    if "1 step" not in stopping and "1 步" not in stopping:
        problems.append("the stopping reason does not state the one-step budget")
    if "external access" not in stopping:
        problems.append("the stopping reason does not state the external-access stop condition")
    delta = episode.get("agendaDelta", {})
    if delta.get("claims"):
        for claim in delta["claims"]:
            if claim.get("tier") != "unverified":
                problems.append(f"delta claim {claim.get('id')} is not tier unverified")
            if not claim.get("sources"):
                problems.append(f"delta claim {claim.get('id')} carries no source")
            if not claim.get("provenance", {}).get("episodeId"):
                problems.append(f"delta claim {claim.get('id')} carries no episode provenance")
    return problems


def check_bonds(bundle) -> list[str]:
    """Quotes, digests, relation vocabulary and the declared relation types."""
    problems = []
    text, digest = bundle["text"], bundle["digest"]
    for evidence in bundle["distillation"].get("evidence", []):
        source = evidence.get("source")
        quote = evidence.get("quote", "")
        problems += unresolved_quotes([(source, quote)], text)
    for scenario in bundle["distillation"].get("testScenarios", []):
        if scenario.get("runId") != bundle["distillation"].get("runId"):
            problems.append(f"{scenario.get('id')}: test scenario points at another run")
        if not scenario.get("seqRange"):
            problems.append(f"{scenario.get('id')}: test scenario carries no anchor")
    if len(bundle["distillation"].get("testScenarios", [])) < 2:
        problems.append("fewer than two test scenarios")
    pinned = bundle["distillation"].get("baseDigest")
    expected = digest.get("E2")
    if pinned != expected:
        problems.append(f"baseDigest {pinned!r} does not match M1's line digest {expected!r}")
    if sha256_line(text.get("E2", "")) != expected:
        problems.append("M1's declared digest is not the digest of its own text")
    assignments = bundle["relations"].get("assignments", [])
    conflict = next((a for a in assignments if a.get("ASSIGNMENT") == "A1"), None)
    if conflict is None or conflict.get("RELATION_TYPE") != "conflicts_with":
        problems.append("M2/M1 is not recorded as a conflict")
    else:
        for name in conflict.get("SKILLS", []):
            problems += unresolved_quotes([(name, text.get(name, ""))], text)
    for assignment in assignments:
        value = assignment.get("RELATION_TYPE")
        if value in (None, "null"):
            if not assignment.get("REASON"):
                problems.append(f"{assignment.get('ASSIGNMENT')}: unclassified with no reason")
            if "shared_part" in assignment.get("REASON", "") and not assignment.get(
                "RELATION_TYPE_STATUS"
            ):
                problems.append(f"{assignment.get('ASSIGNMENT')}: unexplained unclassified relation")
            continue
        if value not in RELATION_VOCABULARY:
            problems.append(f"{assignment.get('ASSIGNMENT')}: {value!r} is outside the vocabulary")
    for revision in bundle["relations"].get("revisions", []):
        if revision.get("operation") != "retire" and not revision.get("skill"):
            problems.append("a non-retire revision carries no rewritten method")
    return problems


CHECKS = (
    ("1 exactly one decision", check_decision),
    ("2 missing outcome is not zero", check_missing_not_zero),
    ("3 no completed external replication claim", check_no_replication_claim),
    ("4 episode budget is one step", check_budget_one),
    ("5 evidence bonds", check_bonds),
)


def load_bundle() -> dict:
    text, digest = load_inputs()
    files = ("distillation.json", "relations.json", "scout.json", "episode.json")
    blobs = {name: read(HERE / name) for name in files}
    return {
        "text": text,
        "digest": digest,
        "blobs": blobs,
        "distillation": load(HERE / "distillation.json"),
        "relations": load(HERE / "relations.json"),
        "scout": load(HERE / "scout.json"),
        "episode": load(HERE / "episode.json"),
    }


def self_tests() -> list[tuple[str, bool, str]]:
    """Break a copy of the data and confirm each check reports it."""
    results: list[tuple[str, bool, str]] = []
    base = load_bundle()

    broken = copy.deepcopy(base)
    broken["distillation"]["decision"] = "merge"
    broken["distillation"]["operation"] = "create"
    fired = bool(check_decision(broken))
    results.append(("negative test: two decision values", fired, "check_decision"))

    broken = copy.deepcopy(base)
    broken["distillation"]["evidence"][3]["quote"] = (
        "Verified output: denominator6, known outcomes6, missing0."
    )
    fired = bool(check_missing_not_zero(broken))
    results.append(("negative test: missing reported as 0", fired, "check_missing_not_zero"))

    broken = copy.deepcopy(base)
    broken["blobs"]["scout.json"] = broken["blobs"]["scout.json"].replace(
        '"status": "unresolved"',
        '"status": "replication completed successfully by an independent group"',
    )
    fired = bool(check_no_replication_claim(broken))
    results.append(("negative test: replication claimed as done", fired, "check_no_replication_claim"))

    broken = copy.deepcopy(base)
    broken["episode"]["plan"]["stepCount"] = 2
    broken["episode"]["plan"]["steps"].append({"step": 2, "action": "inspect more"})
    fired = bool(check_budget_one(broken))
    results.append(("negative test: budget raised to two steps", fired, "check_budget_one"))

    broken = copy.deepcopy(base)
    broken["distillation"]["evidence"][0]["quote"] = "Failure: a paraphrase that is not in the input."
    fired = bool(check_bonds(broken))
    results.append(("negative test: paraphrased evidence quote", fired, "check_bonds"))
    return results


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--report", default="verification-report.txt")
    args = parser.parse_args()

    bundle = load_bundle()
    lines: list[str] = []
    ok = True

    lines.append("bounded local verification - method-learning")
    lines.append(f"workspace: {HERE}")
    lines.append("frozen input: inputs.txt (T, M1, M2, M3 verbatim, per-line sha256)")
    text, digest = bundle["text"], bundle["digest"]
    lines.append(f"frozen lines: {', '.join(sorted(text))}")
    for key in sorted(digest):
        lines.append(f"  {key} {digest[key]}  {text.get(key, '')[:60]}")
    lines.append("")

    for label, check in CHECKS:
        problems = check(bundle)
        state = "PASS" if not problems else "FAIL"
        if problems:
            ok = False
        lines.append(f"[{state}] {label}")
        for problem in problems:
            lines.append(f"        - {problem}")
    lines.append("")

    lines.append("self-tests (each check must fail on deliberately broken data)")
    for label, fired, target in self_tests():
        state = "PASS" if fired else "FAIL"
        if not fired:
            ok = False
        lines.append(f"[{state}] {label} -> {target} reported it")
    lines.append("")

    lines.append(f"decision recorded: {bundle['distillation'].get('decision')}")
    lines.append(
        "unrecorded count recorded: 1 of denominator 6 "
        "(one missing, reported as unknown rather than 0)"
    )
    lines.append("external replication: not performed, recorded unresolved; no artifact claims it")
    lines.append("episode budget: 1 step, stopping on any external access request")
    lines.append("")
    lines.append(f"RESULT: {'ok' if ok else 'failed'}")

